contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address caddress, address[] memory _tos, uint v) public {
        require(_tos.length > 0, "tos must be nonempty");

        bool reverted;
        try c.transfer(from, caddress, _tos, v) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // c.transfer makes a low-level call to caddress with the transferFrom selector.
        // The test contract is the caller; the callee caddress is arbitrary.  If caddress
        // is the zero address or an EOA, the call returns success with empty returndata,
        // and since the code ignores the return value (only checks _s), the transaction
        // does not revert.  Therefore the only way the call reverts is if the low-level
        // call itself fails (e.g. caddress is a contract that reverts).  In the context
        // of a property test we cannot statically know whether a given caddress is a
        // reverting contract, so the strongest general rule is: if the call reverts,
        // then the first low-level call must have failed; if it does not revert, the
        // loop must have completed all its low-level calls successfully.
        // Since we cannot observe intermediate low-level results directly, we express
        // the rule as: reverting implies the target is not a benign EOA/zero address.
        // For the general case where caddress is arbitrary, the only guaranteed
        // non-revert is when _tos.length > 0 and caddress is the zero address (calls
        // to zero address succeed with empty data).  We restrict the input domain to
        // that case to obtain a rule that holds universally.
        require(caddress == address(0), "only test zero-address target");

        assert(reverted == false);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address[] memory _tos, uint v) public {
        require(_tos.length > 0, "tos must be nonempty");

        // Choose a caddress that is guaranteed to be a contract or EOA; we cannot
        // know its code, so the only universally-satisfiable assertion is that the
        // deciding call either completes (returns true) or reverts, and that the
        // revert flag correctly reflects whether the low-level call succeeded.
        // Since we cannot observe the low-level result, we express the observable
        // invariant: a successful `transfer` must have made exactly _tos.length
        // external calls; we can only observe completion vs revert.
        //
        // The only universally true statement about transfer is that it returns
        // true (and does not revert) when _tos is non-empty and every external call
        // succeeds.  Because we cannot construct a guaranteed-successful caddress
        // without knowing code, we restrict the precondition to the case where
        // caddress has no code (EOA/zero address), for which the EVM low-level call
        // returns success with empty returndata and the loop therefore completes.
        address caddress = address(0);
        require(caddress.code.length == 0, "target must be codeless");

        bool reverted;
        try c.transfer(from, caddress, _tos, v) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted == false);
    }
}

